function renderSub(f){const arr=(MODEL.submap[f]||[]).slice().sort((a,b)=>b.CurrentFTE-a.CurrentFTE);let traces=[{type:'bar',name:'Submitted FTE',x:arr.map(x=>x.Subfunction),y:arr.map(x=>x.CurrentFTE),marker:{color:C.gold},text:arr.map(x=>x.CurrentFTE),textposition:'outside'}];if(f==='Finance'){traces.push({type:'bar',name:'APQC P50 share (%)',x:arr.map(x=>x.Subfunction),y:arr.map(x=>x.APQCP50Share||0),marker:{color:C.teal},text:arr.map(x=>(x.APQCP50Share||0).toFixed(1)+'%'),textposition:'outside',yaxis:'y2'})}plot('subfunction-chart',traces,{margin:{l:50,r:55,t:15,b:85},barmode:'group',xaxis:{tickangle:-32,tickfont:{size:8}},yaxis:{title:'Submitted FTE',gridcolor:C.grid},yaxis2:{title:'APQC P50 share (%)',overlaying:'y',side:'right',showgrid:false},legend:{orientation:'h',y:-.38,font:{size:8}}})}fs.addEventListener('change',()=>renderSub(fs.value));renderSub('Finance');

// Organisation charts
plot('layers-chart',[{type:'bar',orientation:'h',y:MODEL.layers.map(x=>'Layer '+x.Layer).reverse(),x:MODEL.layers.map(x=>x.EmployeeCount).reverse(),marker:{color:MODEL.layers.map((x,i)=>i===MODEL.layers.length-1?C.gold:C.teal).reverse()},text:MODEL.layers.map(x=>x.EmployeeCount).reverse(),textposition:'outside'}],{margin:{l:75,r:35,t:15,b:35},xaxis:{title:'Employees',gridcolor:C.grid},showlegend:false});
plot('spans-chart',[{type:'bar',x:MODEL.spans.map(x=>x.SpanBand),y:MODEL.spans.map(x=>x.ManagerCount),marker:{color:MODEL.spans.map(x=>['1','2','3'].includes(x.SpanBand)?C.red:C.teal)},text:MODEL.spans.map(x=>x.ManagerCount),textposition:'outside'}],{margin:{l:45,r:20,t:15,b:45},xaxis:{title:'Direct reports per manager'},yaxis:{title:'Managers',gridcolor:C.grid},showlegend:false});
const narrow=MODEL.functions.filter(x=>x.NarrowManagers>0).sort((a,b)=>b.NarrowManagers-a.NarrowManagers);
plot('narrow-chart',[{type:'bar',orientation:'h',y:narrow.map(x=>x.Function).reverse(),x:narrow.map(x=>x.NarrowManagers).reverse(),marker:{color:C.red},text:narrow.map(x=>x.NarrowManagers).reverse(),textposition:'outside'}],{margin:{l:110,r:30,t:10,b:35},xaxis:{title:'Managers with ≤3 reports',gridcolor:C.grid},showlegend:false});
function donut(id,labels,values,title,colors){plot(id,[{type:'pie',hole:.68,labels,values,textinfo:'none',marker:{colors},hovertemplate:'%{label}: %{value:,.1f}<extra></extra>'}],{margin:{l:5,r:5,t:32,b:5},showlegend:true,legend:{orientation:'h',y:-.1,font:{size:7}},annotations:[{text:title,x:.5,y:.5,showarrow:false,font:{size:10,color:C.text}}]})}
donut('mgr-fte-donut',['Managers','Individual contributors'],[59,301],'FTE mix',[C.gold,C.teal]);donut('mgr-reward-donut',['Managers','Individual contributors'],[108.7,109.7],'Reward mix',[C.gold,C.teal]);donut('fb-reward-donut',['Back office','Front office'],[97.8,120.5],'Reward by type',[C.red,C.teal]);

// Timeline, action and quality tables
const tl=document.getElementById('timeline');MODEL.data.timeline.forEach(x=>tl.insertAdjacentHTML('beforeend',`<div class="tl"><strong>${x.Timing}</strong>${x.Action}<div style="color:var(--muted);margin-top:3px">${x.Output}</div></div>`));
const ab=document.getElementById('action-body');MODEL.data.actions.forEach(x=>{let cls=x.Priority==='High'?'p-high':x.Priority==='Medium'?'p-medium':'p-selective';ab.insertAdjacentHTML('beforeend',`<tr><td><b>${x.Function}</b><br><span class="pill ${cls}">${x.Priority}</span></td><td>${x.FTEReductionLow}–${x.FTEReductionHigh}</td><td>SAR ${x.SavingLowSARm.toFixed(1)}–${x.SavingHighSARm.toFixed(1)}m</td><td>${x.Action}</td><td>${x.Owner}</td><td>${x.Timing}</td><td><span class="pill p-medium">Not started</span></td></tr>`);});
const qb=document.getElementById('quality-body');MODEL.data.quality.forEach(x=>{let cls=x.Status==='Available'?'p-selective':'p-high';qb.insertAdjacentHTML('beforeend',`<tr><td>${x.DataItem}</td><td><span class="pill ${cls}">${x.Status}</span></td><td>${x.Use}</td><td>${x.Action}</td></tr>`);});

(function(){var el=document.getElementById('startup-status');if(el)el.remove();})();
